  #define PDM_FILTER_CTRL_OVERRIDERIGHTSOFTMUTE_Max (0x1UL) /*!< Max enumerator value of OVERRIDERIGHTSOFTMUTE field.          */
  #define PDM_FILTER_CTRL_OVERRIDERIGHTSOFTMUTE_Disable (0x0UL) /*!< No action                                                 */
  #define PDM_FILTER_CTRL_OVERRIDERIGHTSOFTMUTE_Enable (0x1UL) /*!< override and disable soft mute                             */

/* OVERRIDELEFTSOFTMUTE @Bit 7 : Override soft mute enable for left channel */
  #define PDM_FILTER_CTRL_OVERRIDELEFTSOFTMUTE_Pos (7UL) /*!< Position of OVERRIDELEFTSOFTMUTE field.                          */
  #define PDM_FILTER_CTRL_OVERRIDELEFTSOFTMUTE_Msk (0x1UL << PDM_FILTER_CTRL_OVERRIDELEFTSOFTMUTE_Pos) /*!< Bit mask of
                                                                            OVERRIDELEFTSOFTMUTE field.*/
  #define PDM_FILTER_CTRL_OVERRIDELEFTSOFTMUTE_Min (0x0UL) /*!< Min enumerator value of OVERRIDELEFTSOFTMUTE field.            */
  #define PDM_FILTER_CTRL_OVERRIDELEFTSOFTMUTE_Max (0x1UL) /*!< Max enumerator value of OVERRIDELEFTSOFTMUTE field.            */
  #define PDM_FILTER_CTRL_OVERRIDELEFTSOFTMUTE_Disable (0x0UL) /*!< No action                                                  */
  #define PDM_FILTER_CTRL_OVERRIDELEFTSOFTMUTE_Enable (0x1UL) /*!< override and disable soft mute                              */

/* GAINADD0P25 @Bit 8 : Add +0.25dB to the gain stage */
  #define PDM_FILTER_CTRL_GAINADD0P25_Pos (8UL)      /*!< Position of GAINADD0P25 field.                                       */
  #define PDM_FILTER_CTRL_GAINADD0P25_Msk (0x1UL << PDM_FILTER_CTRL_GAINADD0P25_Pos) /*!< Bit mask of GAINADD0P25 field.       */
  #define PDM_FILTER_CTRL_GAINADD0P25_Min (0x0UL)    /*!< Min enumerator value of GAINADD0P25 field.                           */
  #define PDM_FILTER_CTRL_GAINADD0P25_Max (0x1UL)    /*!< Max enumerator value of GAINADD0P25 field.                           */
  #define PDM_FILTER_CTRL_GAINADD0P25_Disable (0x0UL) /*!< Nothing added                                                       */
  #define PDM_FILTER_CTRL_GAINADD0P25_Enable (0x1UL) /*!< +0.25dB added                                                        */

/* MINORSTEP025CUSTOM @Bit 9 : Compensates Gain with +0.25dB */
  #define PDM_FILTER_CTRL_MINORSTEP025CUSTOM_Pos (9UL) /*!< Position of MINORSTEP025CUSTOM field.                              */
  #define PDM_FILTER_CTRL_MINORSTEP025CUSTOM_Msk (0x1UL << PDM_FILTER_CTRL_MINORSTEP025CUSTOM_Pos) /*!< Bit mask of
                                                                            MINORSTEP025CUSTOM field.*/
