  #define PDM_FILTER_CTRL_MINORSTEP025CUSTOM_Max (0x1UL) /*!< Max enumerator value of MINORSTEP025CUSTOM field.                */
  #define PDM_FILTER_CTRL_MINORSTEP025CUSTOM_Disable (0x0UL) /*!< Nothing added                                                */
  #define PDM_FILTER_CTRL_MINORSTEP025CUSTOM_Enable (0x1UL) /*!< +0.25dB added                                                 */

/* MINORSTEP050CUSTOM @Bits 10..13 : Compensates Gain with +0.5dB steps */
  #define PDM_FILTER_CTRL_MINORSTEP050CUSTOM_Pos (10UL) /*!< Position of MINORSTEP050CUSTOM field.                             */
  #define PDM_FILTER_CTRL_MINORSTEP050CUSTOM_Msk (0xFUL << PDM_FILTER_CTRL_MINORSTEP050CUSTOM_Pos) /*!< Bit mask of
                                                                            MINORSTEP050CUSTOM field.*/
