  #define PDM_FILTER_CTRL_SOFTCYCLES_Max (0xFUL)     /*!< Max size of SOFTCYCLES field.                                        */

/* DATASAMPLEDELAY @Bits 19..20 : Input data sampling point delay in PDM_CLK cycels */
  #define PDM_FILTER_CTRL_DATASAMPLEDELAY_Pos (19UL) /*!< Position of DATASAMPLEDELAY field.                                   */
  #define PDM_FILTER_CTRL_DATASAMPLEDELAY_Msk (0x3UL << PDM_FILTER_CTRL_DATASAMPLEDELAY_Pos) /*!< Bit mask of DATASAMPLEDELAY
                                                                            field.*/
