  #define SPU_PERIPH_PERM_PRIVLMAPPING_Min (0x0UL)   /*!< Min enumerator value of PRIVLMAPPING field.                          */
  #define SPU_PERIPH_PERM_PRIVLMAPPING_Max (0x3UL)   /*!< Max enumerator value of PRIVLMAPPING field.                          */
  #define SPU_PERIPH_PERM_PRIVLMAPPING_Unprivileged (0x0UL) /*!< This peripheral is always Unprivileged                        */
  #define SPU_PERIPH_PERM_PRIVLMAPPING_Privileged (0x1UL) /*!< This peripheral is always Privileged                            */
